    /// <summary>
    /// Resolves the full <see cref="ErrorCodeInfo"/> for the given wire
    /// code string. The lookup is ordinal case-sensitive and allocation-free
    /// on the hot path (backed by a <see cref="FrozenDictionary{TKey,TValue}"/>).
    /// </summary>
    /// <param name="code">
    /// The SCREAMING_SNAKE wire code to look up
    /// (e.g. <c>"AUTH_BEARER_MISSING"</c>).
    /// </param>
    /// <param name="info">
    /// When the method returns <see langword="true"/>, contains the full
    /// <see cref="ErrorCodeInfo"/> for the code; otherwise the default value.
    /// </param>
    /// <returns>
    /// <see langword="true"/> when the code is registered;
    /// <see langword="false"/> for any unknown code (including empty /
    /// null / wrong-case).
    /// </returns>
    public static bool TryResolve(string? code, out ErrorCodeInfo info)
    {
        if (code is null)
        {
            info = default;
            return false;
        }

        return sr_lookup.TryGetValue(code, out info);
    }

    /// <summary>
    /// Convenience nullable overload of <see cref="TryResolve"/>. Returns
    /// <see langword="null"/> for any unknown code.
    /// </summary>
    /// <param name="code">The SCREAMING_SNAKE wire code to look up.</param>
    /// <returns>
    /// The <see cref="ErrorCodeInfo"/> for the code, or
    /// <see langword="null"/> when the code is not registered.
    /// </returns>
    public static ErrorCodeInfo? Resolve(string? code) =>
        TryResolve(code, out var info) ? info : null;
